pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: actor will be the caller (must be current owner), newOwner is the desired owner argument
    function testFuzz_property(address actor, address newOwner) public {
        // keep actor non-zero (owners are typically non-zero addresses)
        vm.assume(actor != address(0));
        // ensure actor is not the zero address and newOwner can be any address (including zero)

        // Make the deployed contract's owner be `actor` by performing the constructor-set owner (deployer is this test contract)
        // The constructor set owner to address(this). To let `actor` be the current owner, we first transfer ownership to actor by calling setOwner as the current owner (this test contract).
        bool ok;
        // call setOwner as the current owner (this contract) to set owner to actor
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        // this must succeed on the reference contract; require it to proceed the scenario
        assertTrue(ok);

        // Now act as `actor` (the current owner) and call setOwner(newOwner)
        vm.prank(actor);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after a successful call by the current owner, owner() equals the provided newOwner
        // We assert this by reading the public getter c.owner()
        assertTrue(c.owner() == newOwner);
    }
}

