pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: the new owner candidate and the actor who calls setOwner
    function testFuzz_property(address newOwner, address caller) public {
        // Keep addresses wide but avoid the zero-address for clarity (still admissible if zero, but allow fuzzer to explore)
        // Ensure caller is not the zero address so we can prank from it
        vm.assume(caller != address(0));

        // The contract's constructor sets owner = msg.sender (test contract). The test contract (this) is the owner.
        // We want to simulate the test contract calling setOwner; but setOwner is public and protected by onlyOwner,
        // so only the current owner (this contract) can call it. We'll have this test contract perform the call.
        // However, to allow fuzzing of the 'caller' parameter as an independent actor (to distinguish cases
        // where newOwner == caller or newOwner != caller), we do not rely on caller to actually call setOwner.

        // Record expectation: after this contract (the current owner) calls setOwner(newOwner), c.owner() must equal newOwner.
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always succeeds (onlyOwner passes because this contract is owner)
        // and sets owner exactly to the provided newOwner. The mutant will set owner to msg.sender (this contract)
        // instead, so when newOwner != address(this) the mutant's owner differs.

        // Single assertion reading c: if the call succeeded, owner must equal the provided newOwner.
        // This holds for all inputs on the reference; the mutant will fail for any newOwner != address(this).
        assertTrue(!ok || c.owner() == newOwner);
    }
}

