pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: newOwner - the fuzzer will supply arbitrary addresses
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid zero address to be more meaningful
        // (zero address is still admissible; we do not exclude it strictly)
        vm.prank(address(this)); // make calls as deployer/owner

        // Precondition: this contract is the owner (set in C constructor)
        address before = c.owner();

        // Call setOwner as the current owner to attempt to change owner to newOwner
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Single assertion: if the call succeeded (ok==true), then c.owner() must equal newOwner.
        // This is the universal property: any successful setOwner by the owner sets the owner variable.
        // The mutant that deletes the assignment will return true but leave owner unchanged, violating this.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted or returned false, the reference implementation never reverts here
            // because onlyOwner and the caller is the owner; but to keep the assertion a single call
            // that reads c's public surface, we assert that owner remains equal to before (still valid)
            // Note: this branch will not be taken for the correct contract when called by the owner.
            assertTrue(c.owner() == before);
        }
    }
}

